import com.railwayteam.railways.registry.CRItems;
import com.simibubi.create.AllBlocks;
import com.tterrag.registrate.util.entry.ItemProviderEntry;
import com.tterrag.registrate.util.entry.RegistryEntry;
import net.createmod.ponder.api.registration.PonderSceneRegistrationHelper;
import net.minecraft.resources.ResourceLocation;

public class CRPonderIndex {
    public static void register(PonderSceneRegistrationHelper<ResourceLocation> helper) {
        PonderSceneRegistrationHelper HELPER = helper.withKeyFunction(RegistryEntry::getId);
        HELPER.forComponents((Object[])new ItemProviderEntry[]{CRBlocks.SEMAPHORE}).addStoryBoard("semaphore", TrainScenes::signaling);
        HELPER.forComponents((Object[])new ItemProviderEntry[]{CRBlocks.TRACK_COUPLER}).addStoryBoard("coupler", TrainScenes::coupling);
        HELPER.forComponents(CRItems.ITEM_CONDUCTOR_CAP.values()).addStoryBoard("conductor", ConductorScenes::constructing).addStoryBoard("conductor_redstone", ConductorScenes::redstoning).addStoryBoard("conductor", ConductorScenes::toolboxing);
        HELPER.forComponents((Object[])new ItemProviderEntry[]{AllBlocks.ANDESITE_DOOR, AllBlocks.BRASS_DOOR, AllBlocks.COPPER_DOOR, AllBlocks.TRAIN_DOOR, AllBlocks.FRAMED_GLASS_DOOR}).addStoryBoard("door_modes", DoorScenes::modes);
        HELPER.forComponents((Object[])new ItemProviderEntry[]{CRBlocks.ANDESITE_SWITCH, CRBlocks.BRASS_SWITCH}).addStoryBoard("switch", TrainScenes::trackSwitch);
    }
}

