public class HandcarControlsInteractionBehaviour
extends ControlsInteractionBehaviour {
    public boolean handlePlayerInteraction(Player player, InteractionHand activeHand, BlockPos localPos, AbstractContraptionEntity contraptionEntity) {
        if (!AdventureUtils.isAdventure(player) && AllItems.WRENCH.isIn(player.m_21120_(activeHand)) && contraptionEntity instanceof CarriageContraptionEntity) {
