                return true;
            }
            ItemStack stack = CRBlocks.HANDCAR.asStack();
            if (!player.m_7500_()) {
                player.m_150109_().m_150079_(stack);
            }
            AllSoundEvents.WRENCH_REMOVE.playOnServer(player.f_19853_, (Vec3i)BlockPos.m_274446_((Position)cce.toGlobalVector(Vec3.m_82512_((Vec3i)localPos), 0.5f)), 1.0f, player.m_217043_().m_188501_() * 0.5f + 0.5f);
